<script lang="ts">
  import { onMount,onDestroy } from 'svelte';
  import { open,ask } from '@tauri-apps/plugin-dialog';
  import { roadmapSystemApi as desktop,type AppSet,type LaunchEntry } from '#lib/roadmap-system-api.ts';
  import Notice from '#lib/ui/Notice.svelte';
  let sets=$state<AppSet[]>([]),selected=$state(''),name=$state(''),entries=$state<LaunchEntry[]>([]),argumentTexts=$state<string[]>([]),newKind=$state<LaunchEntry['kind']>('application');
  let busy=$state(false),error=$state(''),message=$state('');let requestId=0;
  function edit(id:string){selected=id;const set=sets.find((s)=>s.id===id);name=set?.name??'';entries=set?.entries.map((e)=>({...e,args:[...e.args]}))??[];argumentTexts=entries.map((e)=>JSON.stringify(e.args));message='';}
  function newSet(){edit(crypto.randomUUID());}
  async function load(){const id=++requestId;busy=true;error='';try{const next=await desktop.launchSets();if(id===requestId){sets=next;edit(next[0]?.id??crypto.randomUUID());}}catch(e){if(id===requestId)error=e instanceof Error?e.message:String(e);}finally{if(id===requestId)busy=false;}}
  async function add(){const id=++requestId;busy=true;error='';try{const paths=await open({title:newKind==='application'?'Choose local applications':'Choose local files',multiple:true,directory:false});if(paths && id===requestId){const selectedPaths=typeof paths==='string'?[paths]:paths;entries=[...entries,...selectedPaths.map((target)=>({kind:newKind,target,args:[]}))];argumentTexts=[...argumentTexts,...selectedPaths.map(()=>'[]')];}}catch(e){if(id===requestId)error=e instanceof Error?e.message:String(e);}finally{if(id===requestId)busy=false;}}
  async function save(){const id=++requestId;busy=true;error='';message='';try{const parsed=entries.map((entry,index)=>{const args:unknown=entry.kind==='application'?JSON.parse(argumentTexts[index]??'[]'):[];if(!Array.isArray(args) || args.some((arg)=>typeof arg!=='string'))throw new Error('Arguments must be a JSON array of strings.');return{...entry,args:args as string[]};});const set={id:selected,name,entries:parsed};const next=[...sets.filter((s)=>s.id!==selected),set].sort((a,b)=>a.name.localeCompare(b.name));await desktop.launchSetsSave(next);if(id===requestId){sets=next;entries=parsed;message='Launch set saved.';}}catch(e){if(id===requestId)error=e instanceof Error?e.message:String(e);}finally{if(id===requestId)busy=false;}}
  async function launch(){const id=++requestId;busy=true;error='';message='';try{const count=await desktop.launchSet(selected);if(id===requestId)message=`Requested launch of ${count} saved applications/files.`;}catch(e){if(id===requestId)error=e instanceof Error?e.message:String(e);}finally{if(id===requestId)busy=false;}}
  async function remove(){const saved=sets.find((s)=>s.id===selected);if(!saved)return;const id=++requestId;busy=true;error='';try{if(!await ask(`Delete the saved launch set “${saved.name}”?\n\nThe applications and files themselves are kept.`,{title:'Delete launch set?',kind:'warning'}))return;if(id!==requestId)return;const next=sets.filter((s)=>s.id!==saved.id);await desktop.launchSetsSave(next);if(id===requestId){sets=next;edit(next[0]?.id??crypto.randomUUID());message='Launch set deleted.';}}catch(e){if(id===requestId)error=e instanceof Error?e.message:String(e);}finally{if(id===requestId)busy=false;}}
  onMount(()=>{void load();});onDestroy(()=>{requestId++;});
</script>
<div class="tool" aria-busy={busy}>
  <Notice kind="info">Save groups of local applications and files, then launch the saved group with one click. Arguments are literal lists passed to applications. URLs, network paths and shell scripts are not accepted.</Notice>
  <label class="field"><span class="field-label">Saved launch set</span><select class="input" value={selected} onchange={(e)=>edit(e.currentTarget.value)} disabled={busy}><option value="">Choose a saved set</option>{#each sets as set}<option value={set.id}>{set.name}</option>{/each}</select></label>
  <div class="row"><button class="btn" disabled={busy} onclick={newSet}>New set</button><button class="btn" disabled={busy} onclick={load}>Reload saved sets</button></div>
  <label class="field"><span class="field-label">Set name</span><input class="input" maxlength="200" bind:value={name} disabled={busy} /></label>
  <div class="row"><label class="field"><span class="field-label">Add target type</span><select class="input" bind:value={newKind} disabled={busy}><option value="application">Application</option><option value="file">File (default application)</option></select></label><button class="btn" disabled={busy || entries.length>=32} onclick={add}>Choose targets…</button></div>
  {#each entries as entry,index}<section class="card entry"><div class="row"><strong>{entry.kind==='application'?'Application':'File'}</strong><span class="path">{entry.target}</span><button class="btn" disabled={busy} aria-label={`Remove ${entry.target}`} onclick={()=>{entries=entries.filter((_,i)=>i!==index);argumentTexts=argumentTexts.filter((_,i)=>i!==index);}}>Remove</button></div>{#if entry.kind==='application'}<label class="field"><span class="field-label">Arguments (JSON string array)</span><input class="input mono" bind:value={argumentTexts[index]} disabled={busy} placeholder={'["--example", "a value"]'} /></label>{/if}</section>{/each}
  <div class="row"><button class="btn" disabled={busy || !name.trim() || !entries.length} onclick={save}>Save set</button><button class="btn btn-primary" disabled={busy || !sets.some((s)=>s.id===selected)} onclick={launch}>Launch saved set</button><button class="btn" disabled={busy || !sets.some((s)=>s.id===selected)} onclick={remove}>Delete saved set…</button></div>
  {#if !entries.length}<Notice kind="info">Add one or more local targets to begin. Save edits before launching.</Notice>{/if}{#if message}<Notice kind="success">{message}</Notice>{/if}{#if error}<Notice kind="error">{error}</Notice>{/if}
</div>
<style>.tool{display:grid;gap:var(--s-4)}.row{display:flex;align-items:center;gap:var(--s-3);flex-wrap:wrap}.entry{display:grid;gap:var(--s-3);padding:var(--s-4)}.path{flex:1;min-width:0;overflow-wrap:anywhere}</style>
